    async head(target: ImportObjectTarget) { return this.objects.get(`${target.bucket}/${target.key}`) ?? null; }
    async put(target: ImportObjectTarget) { const identity = { etag: '"stage-etag"', versionId: 'stage-version' }; this.objects.set(`${target.bucket}/${target.key}`, identity); return identity; }
    async copy(_source: ImportObjectTarget & ImportObjectIdentity, target: ImportObjectTarget) { this.copies++; if (this.failCopyBefore) throw new Error('outcome unknown'); const identity = { etag: '"canonical-etag"', versionId: 'canonical-version' }; this.objects.set(`${target.bucket}/${target.key}`, identity); await this.afterCopy?.(); return identity; }
