/** One uploaded file reviewed as "Amet Collection": two primaries, a featured entry and the label Sit Records unless `change` says otherwise. */
async function reviewed(storage: Storage, change: (draft: ImportDraftV2) => void = () => undefined): Promise<AdminImportDetailV2> {
    const slotId = randomUUID(), created = await createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Amet', files: [{ slotId, filename: file().originalname, relativePath: file().originalname, byteLength: file().size }] } });
    const uploaded = await uploadAdminImportAsset(by, created.item.id, slotId, mutation(1), file(), storage);
    return (await editImportDraft(by, created.item.id, uploaded.item, draft => {
        Object.assign(draft.album, { title: 'Amet Collection', artists: entries(), label: { name: 'Sit Records', musicBrainzId: null }, releaseDate, visibility: 'public' });
        Object.assign(draft.tracks[0], { title: 'Consectetur', discNumber: null, trackNumber: 1 }); change(draft);
    })).item;
}
type Choice = Partial<Pick<ImportDecisionDtoV2, 'action' | 'candidateId' | 'candidateRevision'>>;
/**
 * Saves one decision per entry, the label, the Album and each track: create a distinct identity unless `choose` (keyed by entry
 * name, 'label', 'album' or slot) gives another choice, or null to save no decision for it.
 */
async function decided(item: AdminImportDetailV2, choose: Record<string, Choice | null> = {}): Promise<AdminImportDetailV2> {
    const fresh = { action: 'create-distinct' as const, candidateId: null, candidateRevision: null }, kept = (key: string) => choose[key] !== null;
    const decisions = [
        ...item.draft.album.artists.filter(value => kept(value.name)).map(value => ({ scope: 'artist', slotId: null, entryKey: value.key, boundName: value.name, ...fresh, ...choose[value.name] })),
        ...(item.draft.album.label && kept('label') ? [{ scope: 'label', slotId: null, entryKey: null, boundName: item.draft.album.label.name, ...fresh, ...choose.label }] : []),
        ...(kept('album') ? [{ scope: 'album', slotId: null, entryKey: null, boundName: null, ...fresh, ...choose.album }] : []),
        ...item.draft.tracks.filter(track => kept(track.slotId)).map(track => ({ scope: 'track', slotId: track.slotId, entryKey: null, boundName: null, ...fresh, ...choose[track.slotId] }))
    ];
    return (await decideAdminImportDuplicates(by, item.id, { ...mutation(item.revision), decisions })).item;
}
const reuse = (candidate: ImportDuplicateCandidate): Choice => ({ action: 'reuse', candidateId: candidate.id, candidateRevision: candidate.revision });
const candidate = async (item: AdminImportDetailV2, kind: ImportDuplicateCandidate['kind'], label: string) => (await adminImportDuplicateCandidates(by, item.id)).items.find(value => value.kind === kind && value.label === label)!;
