test('two primaries, a featured entry and a new label publish their Credits in draft order, and listeners see the Album under each', async () => {
    const storage = new Storage(), item = await decided(await reviewed(storage)), approved = await publishAdminImport(by, item.id, approvalBody(item)), frozen = (await stored(item.id)).media!.publication!;
    assert.equal(approved.item.publication, 'preparing');
    assert.deepEqual([frozen.schemaVersion, frozen.artists!.map(value => [value.entryKey, value.newArtist, value.candidateRevision]), frozen.label!.newOrganization, frozen.artistId], [3, item.draft.album.artists.map(value => [value.key, true, null]), true, frozen.artists![0].artistId]);
    await runAdminImportPublicationOnce(storage, item.id);
    const done = (await getAdminImport(by, item.id)).item; assert.equal(done.publication, 'complete');
    const { albumId, artistIds, organizationId, trackIds } = done.published!, [lorem, ipsum, dolor] = artistIds;
    assert.deepEqual([artistIds, organizationId], [frozen.artists!.map(value => value.artistId), frozen.label!.organizationId]);
    const album = await row('albums', albumId);
    assert.deepEqual(album!.credits, [
        { creditId: `import_primary_${lorem}`, subjectType: 'artist', subjectId: lorem, role: 'primary', order: 0, joinPhrase: ' & ' },
        { creditId: `import_primary_${ipsum}`, subjectType: 'artist', subjectId: ipsum, role: 'primary', order: 1, joinPhrase: ' feat. ' },
        { creditId: `import_featured_${dolor}`, subjectType: 'artist', subjectId: dolor, role: 'featured', order: 2 },
        { creditId: `import_label_${organizationId}`, subjectType: 'organization', subjectId: organizationId, role: 'label', order: 3 }
    ]);
    // Only primaries own the Album in albumIds; every new Artist takes the draft's visibility.
    const artists = await Promise.all(artistIds.map(id => row('artists', id)));
    assert.deepEqual(artists.map(value => [value!.name, value!.albumIds, value!.visibility, value!.lifecycleStatus]), [['Lorem Ensemble', [albumId], 'public', 'ready'], ['Ipsum Quartet', [albumId], 'public', 'ready'], ['Dolor Soloist', [], 'public', 'ready']]);
    // The Track holds the primary Credits; the featured entry and the label stay on the Album, and so does ' feat. ', which led into them.
    const track = await row('audioTracks', trackIds[0]), { joinPhrase: _feat, ...lastPrimary } = album!.credits[1];
    assert.deepEqual([track!.credits, track!.artistIds, track!.visibility, track!.releaseDate], [[album!.credits[0], lastPrimary], [lorem, ipsum], 'public', releaseDate]);
    const organization = await row('organizations', organizationId!);
    assert.deepEqual([organization!.name, organization!.organizationType, organization!.description, organization!.visibility, organization!.lifecycleStatus, organization!.createdBy, organization!.catalogSearchGrams],
        ['Sit Records', 'label', '', 'public', 'ready', by, catalogSearchProjection('Sit Records').catalogSearchGrams]);
    // Listener reads: the label's releases, primary Discography, featured Collaborations, and followers of the featured Artist.
    assert.deepEqual((await getListenerOrganization(organizationId!))!.releases.map(value => value.id), [albumId]);
    assert.deepEqual((await getListenerArtist(lorem))!.discography.map(value => value.id), [albumId]);
    const featured = (await getListenerArtist(dolor))!; assert.deepEqual([featured.discography, featured.collaborations.map(value => value.id)], [[], [albumId]]);
    await followArtist(listener.toHexString(), dolor);
    const releases = await resolveFollowedArtistReleases(listener.toHexString(), 20, true, new Date('2026-03-20T12:00:00Z'));
    assert.ok(releases.some(value => value.contentType === 'album' && value.contentId === albumId && value.reason.artist.id === dolor), JSON.stringify(releases));
    // The listener Album is exactly the frozen contract fixture (no new fields), with synthetic IDs.
    const listenerAlbum = await getListenerAlbum(albumId), fixture = JSON.parse(readFileSync(new URL('../../contracts/listener/v1/fixtures/album-multi-artist-label.json', import.meta.url), 'utf8'));
    assert.deepEqual(substitute(listenerAlbum, { [albumId]: '64b000000000000000000011', [trackIds[0]]: '64b000000000000000000012', [lorem]: '64b000000000000000000013', [ipsum]: '64b000000000000000000014', [dolor]: '64b000000000000000000015', [organizationId!]: '64b000000000000000000016' }), fixture);
    assert.deepEqual(new Set(listenerAlbum!.album.artistNames).size, listenerAlbum!.album.artistNames.length);
});

test('a hidden import exposes no new Artist or Organization, and reused Artists and labels keep their own values', async () => {
    const storage = new Storage();
    const hidden = await publishNow(storage, await decided(await reviewed(storage, draft => { draft.album.visibility = 'hidden'; })));
    const { albumId, artistIds, organizationId } = hidden.published!;
    assert.deepEqual((await Promise.all(artistIds.map(id => row('artists', id)))).map(value => value!.visibility), ['hidden', 'hidden', 'hidden']);
    assert.equal((await row('organizations', organizationId!))!.visibility, 'hidden');
    for (const id of artistIds) assert.equal(await getListenerArtist(id), null);
    assert.equal(await getListenerOrganization(organizationId!), null); assert.equal(await getListenerAlbum(albumId), null);
    // Reused records: a public Artist for one primary, another for the featured entry, and a distributor Organization as the label.
    const ipsum = new ObjectId(), dolor = new ObjectId(), label = new ObjectId();
    await db().collection('artists').insertMany([{ _id: ipsum, name: 'Ipsum Quartet', bio: 'Existing bio', albumIds: [], visibility: 'public', lifecycleStatus: 'ready' }, { _id: dolor, name: 'Dolor Soloist', bio: 'Guest bio', albumIds: [], visibility: 'public', lifecycleStatus: 'ready' }]);
    await db().collection('organizations').insertOne({ _id: label, name: 'Sit Records', organizationType: 'distributor', description: 'Existing description', visibility: 'public', lifecycleStatus: 'ready', referenceRevision: 0 });
    const before = Object.fromEntries(await Promise.all([['artists', ipsum], ['artists', dolor], ['organizations', label]].map(async ([collection, id]) => [String(id), await row(collection as string, String(id))])));
    const item = await reviewed(storage, draft => { draft.album.visibility = 'hidden'; draft.album.title = 'Amet Reprise'; });
    const all = (await adminImportDuplicateCandidates(by, item.id)).items, pick = (kind: string, id: ObjectId) => all.find(value => value.kind === kind && value.id === id.toHexString())!;
    const done = await publishNow(storage, await decided(item, { 'Ipsum Quartet': reuse(pick('artist', ipsum)), 'Dolor Soloist': reuse(pick('artist', dolor)), label: reuse(pick('organization', label)) }));
    assert.deepEqual([done.published!.artistIds.slice(1), done.published!.organizationId], [[ipsum.toHexString(), dolor.toHexString()], label.toHexString()]);
    for (const [id, value] of Object.entries(before)) {
        const after = await row(id === label.toHexString() ? 'organizations' : 'artists', id), { albumIds, referenceRevision, lifecycleUpdatedAt, lifecycleError, ...kept } = after!;
        const { albumIds: beforeIds, referenceRevision: beforeRevision, ...expected } = value!;
        // Only the fence fields and a reused primary's albumIds change; name, bio, description, type and visibility are kept.
        assert.deepEqual(kept, expected, id); assert.equal(referenceRevision, (beforeRevision ?? 0) + 1, id); assert.ok(lifecycleUpdatedAt instanceof Date, id); assert.equal(lifecycleError, null, id);
        assert.deepEqual(albumIds, id === ipsum.toHexString() ? [done.published!.albumId] : beforeIds, id);
    }
    assert.equal((await row('organizations', label.toHexString()))!.organizationType, 'distributor');
    // The hidden Album hides its public Tracks; the reused public records stay public but expose no hidden Album.
    assert.deepEqual((await getListenerArtist(ipsum.toHexString()))!.discography, []);
});

