test('a reused featured Artist or label that changes after approval is a catalog conflict that mints nothing; cancel, cleanup and a new review publish fresh identities', async () => {
    for (const changed of ['artist', 'label'] as const) {
        for (const name of ['artists', 'organizations', 'albums', 'audioTracks']) await db().collection(name).deleteMany({});
        const storage = new Storage(), dolor = new ObjectId(), label = new ObjectId();
        await db().collection('artists').insertOne({ _id: dolor, name: 'Dolor Soloist', albumIds: [], visibility: 'public', lifecycleStatus: 'ready' });
        await db().collection('organizations').insertOne({ _id: label, name: 'Sit Records', organizationType: 'label', visibility: 'public', lifecycleStatus: 'ready' });
        let item = await reviewed(storage); const all = (await adminImportDuplicateCandidates(by, item.id)).items;
        item = await decided(item, { 'Dolor Soloist': reuse(all.find(value => value.id === dolor.toHexString())!), label: reuse(all.find(value => value.id === label.toHexString())!) });
        await publishAdminImport(by, item.id, approvalBody(item)); const first = (await stored(item.id)).media!.publication!;
        storage.afterCopy = async () => { await db().collection(changed === 'artist' ? 'artists' : 'organizations').updateOne({ _id: changed === 'artist' ? dolor : label }, { $set: { name: 'Corrected' } }); };
        await runAdminImportPublicationOnce(storage, item.id); storage.afterCopy = undefined;
        const stalled = await stored(item.id);
        assert.deepEqual([stalled.media!.publication!.state, stalled.media!.publication!.issue], ['needsAttention', 'catalogConflict'], changed);
        assert.deepEqual(await counts(), { artists: 1, organizations: 1, albums: 0, audioTracks: 0, imageAssets: 0 }, changed);
        const cancelled = await cancelAdminImportPublication(other.toHexString(), item.id, { ...mutation(stalled.revision), publicationOperationId: first.operationId }, storage);
        assert.deepEqual([cancelled.item.publication, cancelled.item.publicationRecovery!.cleanupPending], ['cancelled', false], changed);
        // The corrected record is reviewed again under its corrected name.
        let next = (await editImportDraft(by, item.id, cancelled.item, draft => { if (changed === 'artist') draft.album.artists[2].name = 'Corrected'; else draft.album.label = { name: 'Corrected', musicBrainzId: null }; })).item;
        const fresh = (await adminImportDuplicateCandidates(by, item.id)).items;
        next = await decided(next, { [changed === 'artist' ? 'Corrected' : 'Dolor Soloist']: reuse(fresh.find(value => value.id === dolor.toHexString())!), label: reuse(fresh.find(value => value.id === label.toHexString())!) });
        const done = await publishNow(storage, next);
        assert.equal(done.publication, 'complete', changed);
        assert.notEqual(done.published!.albumId, first.albumId, changed); assert.notDeepEqual(done.published!.artistIds.slice(0, 2), first.artists!.slice(0, 2).map(value => value.artistId), changed);
        assert.deepEqual([done.published!.artistIds[2], done.published!.organizationId], [dolor.toHexString(), label.toHexString()], changed);
    }
});

