    const created = await createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Amet', files: [file(), changed].map((value, index) => ({ slotId: slots[index], filename: value.originalname, relativePath: value.originalname, byteLength: value.size })) } });
    let uploaded = await uploadAdminImportAsset(by, created.item.id, slots[0], mutation(1), file(), storage);
    uploaded = await uploadAdminImportAsset(by, created.item.id, slots[1], mutation(uploaded.item.revision), changed, storage);
    let item = (await editImportDraft(by, created.item.id, uploaded.item, draft => {
        Object.assign(draft.album, { title: 'Amet Collection', artists: [], label: null });
        draft.tracks.forEach(track => Object.assign(track, track.slotId === slots[0] ? { title: 'Consectetur', trackNumber: 1 } : { title: 'Appended', trackNumber: 2 }));
    })).item;
